-- Reviewed production SQL contract fixture only. No provider calls or public posts.
-- Existing dedicated QA owner and actual active session; all new rows rolled back.
-- Never replace authority helpers, disable triggers or print auth credentials.
BEGIN;
SET LOCAL lock_timeout='3s';SET LOCAL statement_timeout='45s';SET LOCAL idle_in_transaction_session_timeout='60s';
CREATE TEMP TABLE qa_owner_save_results(label text PRIMARY KEY,passed boolean) ON COMMIT DROP;
GRANT INSERT,SELECT ON qa_owner_save_results TO authenticated,service_role;
CREATE FUNCTION pg_temp.qa_owner_save_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'qa_owner_save_assertion_failed:%',label;END IF;INSERT INTO pg_temp.qa_owner_save_results VALUES(label,true);END$$;
DO $qa$
DECLARE executor name:=current_user;
 ws constant uuid:='053a5656-b19b-48a4-8721-65c4674f647c';actor constant uuid:='21a04e78-e3b1-448e-8517-47aad25dd5da';account constant uuid:='2ba5b8e3-4fe9-4ec7-a3bf-7f616fcf07fd';
 listing constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140001';foreign_listing constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140002';other_ws constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140003';channel_id constant bigint:=-9126101400001;ephemeral_session constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140004';fixture_source constant text:='qa-publisher-aged-rollback-20261014';item jsonb;payload jsonb;resource_receipt jsonb;slot_receipt jsonb;source_record jsonb;due jsonb;snapshot jsonb;original_meta jsonb;sid uuid;category bigint;receipt jsonb;replay jsonb;post zoi.social_posts;denied boolean;
BEGIN
 IF EXISTS(SELECT 1 FROM zoi.listings WHERE id IN(listing,foreign_listing))OR EXISTS(SELECT 1 FROM zoi.workspaces WHERE id=other_ws)OR EXISTS(SELECT 1 FROM zoi.social_channels WHERE id=channel_id)OR EXISTS(SELECT 1 FROM auth.sessions WHERE id=ephemeral_session)OR EXISTS(SELECT 1 FROM zoi.editorial_sources WHERE id=fixture_source)OR EXISTS(SELECT 1 FROM zoi.social_posts WHERE meta->>'qa_publisher_fixture'='20261014')THEN RAISE EXCEPTION 'qa_publisher_fixture_collision';END IF;
 IF NOT EXISTS(SELECT 1 FROM zoi.workspaces w JOIN zoi.workspace_members m ON m.workspace_id=w.id JOIN zoi.user_profiles p ON p.id=m.profile_id JOIN auth.users u ON u.id=p.auth_user_id WHERE w.id=ws AND w.name='Zoi isolated QA 2026-09-30' AND w.owner_profile_id=actor AND m.profile_id=actor AND m.role='owner' AND p.auth_user_id=account AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false)AND(u.banned_until IS NULL OR u.banned_until<=clock_timestamp()))THEN RAISE EXCEPTION 'dedicated_qa_authority_unavailable';END IF;
 SELECT s.id INTO sid FROM auth.sessions s WHERE s.user_id=account AND(s.not_after IS NULL OR s.not_after>clock_timestamp())ORDER BY s.created_at DESC NULLS LAST LIMIT 1;IF sid IS NULL THEN RAISE EXCEPTION 'dedicated_qa_current_session_unavailable';END IF;
 IF to_regprocedure('public.booking_owner_save(uuid,uuid,text,jsonb)')IS NULL THEN RAISE EXCEPTION 'owner_save_schema_unavailable';END IF;
 SELECT id INTO category FROM zoi.categories WHERE slug='restaurants'LIMIT 1;IF category IS NULL THEN RAISE EXCEPTION 'qa_category_unavailable';END IF;
 IF EXISTS(SELECT 1 FROM zoi.booking_settings WHERE workspace_id=ws)OR EXISTS(SELECT 1 FROM zoi.booking_owner_save_receipts WHERE request_id IN('c1eb6d31-5454-4c5c-b52b-cd2610140020','c1eb6d31-5454-4c5c-b52b-cd2610140021','c1eb6d31-5454-4c5c-b52b-cd2610140022','c1eb6d31-5454-4c5c-b52b-cd2610140023','c1eb6d31-5454-4c5c-b52b-cd2610140024','c1eb6d31-5454-4c5c-b52b-cd2610140025'))THEN RAISE EXCEPTION 'owner_save_fixture_collision';END IF;
 INSERT INTO zoi.workspaces(id,name,kind,owner_profile_id,created_by_auth)VALUES(other_ws,'Rollback-only owner save workspace','business',actor,account);
 -- This uncommitted page is invisible to other sessions and rolled back. Booking
 -- remains disabled; the fixture never calls a publisher, provider or worker.
 INSERT INTO zoi.listings(id,owner_workspace_id,entity_type,name,slug,primary_category_id,publish_status,moderation_status,marketplace_status,profile,city,country,address)VALUES(listing,ws,'business','Rollback-only owner save page','qa-owner-save-rollback-20261014',category,'draft','clean','active','{}','Athens','Greece','1 Rollback Fixture Street');
 PERFORM pg_temp.qa_owner_save_assert((SELECT publish_status='draft' FROM zoi.listings WHERE id=listing),'actual_insert_preserves_explicit_draft');
 UPDATE zoi.listings SET publish_status='published' WHERE id=listing;
 PERFORM pg_temp.qa_owner_save_assert((SELECT publish_status='published' AND owner_workspace_id=ws AND moderation_status='clean' FROM zoi.listings WHERE id=listing),'actual_publish_gate_accepts_complete_owned_fixture');
 INSERT INTO auth.sessions(id,user_id,created_at,updated_at,not_after)VALUES(ephemeral_session,account,clock_timestamp(),clock_timestamp(),clock_timestamp()-interval'1 minute');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid)::text,true);PERFORM set_config('request.jwt.claim.sub',account::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 receipt:=public.booking_owner_save_capabilities(ws);PERFORM pg_temp.qa_owner_save_assert(receipt->>'schema_version'='1'AND receipt->>'account'=account::text AND receipt->>'workspace'=ws::text,'actual_current_schema1_capability');
 payload:=jsonb_build_object('expected_version',0,'listing',listing,'timezone','UTC','currency','EUR','enabled',false);
 receipt:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140020','settings',payload);replay:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140020','settings',payload);
 PERFORM pg_temp.qa_owner_save_assert(receipt#>>'{receipt,settings,version}'='1'AND replay->>'replayed'='true'AND replay#>>'{receipt,settings,version}'='1','actual_canonical_disabled_setup_exact_replay');
 payload:='{"id":null,"expected_version":0,"data":{"name":"Rollback-only owner save service20261014","active":true,"duration_minutes":60,"buffer_minutes":0,"price_cents":0}}';
 item:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',payload);replay:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',payload);
 PERFORM pg_temp.qa_owner_save_assert(item->>'account'=account::text AND item->>'actor'=actor::text AND item->>'client_listing_id'=listing::text AND replay#>>'{receipt,item,id}'=item#>>'{receipt,item,id}'AND replay->>'replayed'='true','actual_create_response_retry_same_item_account_profile');
 denied:=false;BEGIN PERFORM public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',jsonb_set(payload,'{data,name}','"Changed nonce payload"'));EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='booking_owner_request_conflict';END;PERFORM pg_temp.qa_owner_save_assert(denied,'changed_nonce_body_refused');
 payload:=jsonb_build_object('id',item#>>'{receipt,item,id}','expected_version',1,'data',jsonb_build_object('name','Rollback-only owner save updated20261014','active',true,'duration_minutes',60,'buffer_minutes',0,'price_cents',0));
 receipt:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140022','service',payload);replay:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140022','service',payload);PERFORM pg_temp.qa_owner_save_assert(receipt#>>'{receipt,item,version}'='2'AND replay#>>'{receipt,item,version}'='2','actual_update_exact_replay_one_version');
 replay:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',item->'payload');PERFORM pg_temp.qa_owner_save_assert(replay#>>'{receipt,item,version}'='1'AND replay#>>'{receipt,item,name}'='Rollback-only owner save service20261014','original_receipt_immutable_after_later_update');
 resource_receipt:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140023','resource','{"id":null,"expected_version":0,"data":{"name":"Rollback-only owner save staff20261014","active":true,"kind":"staff","capacity":1}}');PERFORM pg_temp.qa_owner_save_assert(resource_receipt#>>'{receipt,item,kind}'='staff','actual_canonical_staff_create');
 payload:=jsonb_build_object('id',NULL,'expected_version',0,'service',item#>>'{receipt,item,id}','resource',resource_receipt#>>'{receipt,item,id}','starts_at',clock_timestamp()+interval'2 days','active',false);
 slot_receipt:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140024','slot',payload);replay:=public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140024','slot',payload);PERFORM pg_temp.qa_owner_save_assert(slot_receipt#>>'{receipt,slot,active}'='false'AND replay#>>'{receipt,slot,id}'=slot_receipt#>>'{receipt,slot,id}','actual_hidden_availability_exact_replay_no_public_stock');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.listings SET owner_workspace_id=other_ws WHERE id=listing;EXECUTE 'SET LOCAL ROLE authenticated';
 denied:=false;BEGIN PERFORM public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',item->'payload');EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='booking_owner_client_unavailable';END;PERFORM pg_temp.qa_owner_save_assert(denied,'transferred_current_client_refuses_replay');
 denied:=false;BEGIN PERFORM public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140025','service',item->'payload');EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='booking_owner_client_unavailable';END;PERFORM pg_temp.qa_owner_save_assert(denied,'transferred_current_client_refuses_new_write');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.listings SET owner_workspace_id=ws WHERE id=listing;UPDATE zoi.workspace_members SET role='viewer'WHERE workspace_id=ws AND profile_id=actor;EXECUTE 'SET LOCAL ROLE authenticated';
 denied:=false;BEGIN PERFORM public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',item->'payload');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.qa_owner_save_assert(denied,'viewer_cannot_retrieve_original_private_receipt');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.workspace_members SET role='owner'WHERE workspace_id=ws AND profile_id=actor;PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',ephemeral_session)::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 denied:=false;BEGIN PERFORM public.booking_owner_save(ws,'c1eb6d31-5454-4c5c-b52b-cd2610140021','service',item->'payload');EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='suite_session_unavailable';END;PERFORM pg_temp.qa_owner_save_assert(denied,'expired_session_cannot_retrieve_original_private_receipt');
 EXECUTE format('SET LOCAL ROLE %I',executor);
 PERFORM pg_temp.qa_owner_save_assert((SELECT count(*)=1 FROM zoi.booking_services WHERE workspace_id=ws AND id=(item#>>'{receipt,item,id}')::uuid)AND(SELECT version=2 FROM zoi.booking_services WHERE id=(item#>>'{receipt,item,id}')::uuid),'one_actual_canonical_service_version2');
 PERFORM pg_temp.qa_owner_save_assert(NOT EXISTS(SELECT 1 FROM zoi.booking_owner_save_receipts WHERE request_id='c1eb6d31-5454-4c5c-b52b-cd2610140025'),'refused_request_has_no_receipt');
 PERFORM pg_temp.qa_owner_save_assert(NOT EXISTS(SELECT 1 FROM zoi.bookings WHERE slot_id=(slot_receipt#>>'{receipt,slot,id}')::uuid)AND NOT EXISTS(SELECT 1 FROM zoi.feed_posts WHERE body='Rollback-only owner save service20261014'),'no_customer_booking_or_feed_publication');
END $qa$;
SELECT label,passed FROM qa_owner_save_results ORDER BY label;
ROLLBACK;
SELECT jsonb_build_object('rollback_completed',true,'fixture_receipts_absent',NOT EXISTS(SELECT 1 FROM zoi.booking_owner_save_receipts WHERE request_id IN('c1eb6d31-5454-4c5c-b52b-cd2610140020','c1eb6d31-5454-4c5c-b52b-cd2610140021','c1eb6d31-5454-4c5c-b52b-cd2610140022','c1eb6d31-5454-4c5c-b52b-cd2610140023','c1eb6d31-5454-4c5c-b52b-cd2610140024','c1eb6d31-5454-4c5c-b52b-cd2610140025')),'fixture_services_absent',NOT EXISTS(SELECT 1 FROM zoi.booking_services WHERE name IN('Rollback-only owner save service20261014','Rollback-only owner save updated20261014')),'fixture_resource_absent',NOT EXISTS(SELECT 1 FROM zoi.booking_resources WHERE name='Rollback-only owner save staff20261014'),'fixture_listing_absent',NOT EXISTS(SELECT 1 FROM zoi.listings WHERE id='c1eb6d31-5454-4c5c-b52b-cd2610140001'),'fixture_workspace_absent',NOT EXISTS(SELECT 1 FROM zoi.workspaces WHERE id='c1eb6d31-5454-4c5c-b52b-cd2610140003'),'fixture_session_absent',NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id='c1eb6d31-5454-4c5c-b52b-cd2610140004'),'provider_or_publication_acceptance',false);
